def is_multiply_prime(a):
    if a < 2:
        return False
    prime_factors = 0
    for i in range(2, int(math.sqrt(a)) + 1):
        if a % i == 0:
            if is_prime(i):
                prime_factors += 1
                while a % i == 0:
                    a //= i
    if a > 1 and is_prime(a):
        prime_factors += 1
    return prime_factors == 3

def decimal_to_binary(decimal):
    """Converts a decimal number to binary format with 'db' prefix and suffix."""
    if decimal == 0:
        return "db0db"
    binary = ""
    while decimal > 0:
        binary = str(decimal % 2) + binary
        decimal = decimal // 2
    return "db" + binary + "db"

